      this.input,
      this.offsetToSourcePos(this.state.lastTokEndLoc!.index),
      this.state.start,
    );
  }

  hasFollowingLineBreak(): boolean {
    return hasNewLine(this.input, this.state.end, this.nextTokenStart());
