  NodePrototype.__clone = function (): Node {
    const newNode = new Node(undefined!, this.start, this.loc.start);
    const keys = Object.keys(this) as (keyof Node)[];
    for (let i = 0, length = keys.length; i < length; i++) {
      const key = keys[i];
