import type {Options} from 'ajv';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema compilation', () => {
  it('throws at registration time for an uncompilable schema naming the tool', () => {
    const opts: Options = {strict: false, validateFormats: false, coerceTypes: false, useDefaults: false};
    expect(opts.strict).toBe(false);
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'Has an uncompilable schema',
          inputSchema: {
            type: 'object',
            properties: {field: {type: 'not-a-valid-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_tool/);
  });
});

