parameters.new_string:
  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the registered inputSchema; returns a rejection ToolResponse on schema failure and throws only for unknown tools (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.getValidator(tool, definition);
    if (!validator(input)) {
      const rejectionMessage = this.formatValidationErrors(definition.name, validator.errors);
      log.warn('tool', 'tool input validation failed', {name});
      return {result: rejectionMessage};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private formatValidationErrors(toolName: string, errors?: ErrorObject[] | null): string {
    if (!errors || errors.length === 0) {
      return `Invalid input for tool "${toolName}"`;
    }
    const descriptions = errors.map(err => {
      const fieldPath = err.instancePath
        ? err.instancePath.replace(/^\//, '').replace(/\//g, '.')
        : typeof err.params?.missingProperty === 'string'
          ? err.params.missingProperty
          : '';
      if (err.keyword === 'required' && typeof err.params?.missingProperty === 'string') {
        return `missing required property "${err.params.missingProperty}"`;
      }
      if (err.keyword === 'type' && typeof err.params?.type === 'string') {
        return `property "${fieldPath}" must be of type ${err.params.type}`;
      }
      if (err.keyword === 'enum' && Array.isArray(err.params?.allowedValues)) {
        return `property "${fieldPath}" must be one of allowed values`;
      }
      return fieldPath ? `property "${fieldPath}" ${err.message ?? 'is invalid'}` : (err.message ?? 'invalid input');
    });
    return `Invalid input for tool "${toolName}": ${descriptions.join('; ')}`;
  }
}

